"""Rebuild production REFERENCE rows that the schema-only baseline cannot carry.
Every statement is copied verbatim from Mason's pre-baseline migrations, in filename order,
so the local copy holds the same lookup data production got from those migrations."""
import re, sys, pathlib
repo = pathlib.Path(sys.argv[1]); out = pathlib.Path(sys.argv[2])
TABLES = ('unit_conversions', 'app_settings', 'warehouses', 'quote_pdf_templates')
pat = re.compile(r'^\s*((?:INSERT\s+INTO|UPDATE)\s+(?:public\.)?(%s)\b.*?;)\s*$' % '|'.join(TABLES), re.S | re.I | re.M)
parts = ['-- GENERATED by build-reference-data.py from supabase/migrations (pre-baseline). Do not edit.', 'BEGIN;']
for f in sorted((repo / 'supabase/migrations').glob('*.sql')):
    if f.name[:14] > '20260727174805':
        continue  # post-baseline files are replayed for real by rebuild.sh
    src = '\n'.join(l for l in f.read_text().splitlines() if not l.lstrip().startswith('--'))
    for m in pat.finditer(src):
        stmt = m.group(1)
        if m.group(2).lower() == 'unit_conversions' and stmt.upper().startswith('UPDATE') is False and 'VALUES' not in stmt.upper():
            continue
        parts.append(f'-- from {f.name}\n{stmt}')
parts.append('COMMIT;')
out.write_text('\n'.join(parts) + '\n')
print(len(parts) - 3, 'statements ->', out)
